    const fx = (x + 28000)/70 - D.i0, fy = (y + 28000)/70 - D.j0;
    if (fx < 0 || fy < 0 || fx > D.ni - 1.001 || fy > D.nj - 1.001) return typeof hC === 'function' ? hC(x, y) : -0.3;
    const i = fx | 0, j = fy | 0, u = fx - i, v = fy - j, k = j*D.ni + i;
